public class NewtonRootSolverTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static double round4(double value) {
        return Math.round(value * 10000.0) / 10000.0;
    }

    public static void main(String[] args) {
        try {
            check("sqrt(9.0)", 3.0, round4(NewtonRootSolver.sqrt(9.0, 1e-9)));
            check("sqrt(2.0)", 1.4142, round4(NewtonRootSolver.sqrt(2.0, 1e-9)));
            check("sqrt(0.25)", 0.5, round4(NewtonRootSolver.sqrt(0.25, 1e-12)));
            check("sqrt(1.0)", 1.0, round4(NewtonRootSolver.sqrt(1.0, 1e-9)));
            check("sqrt(1000000.0)", 1000.0, round4(NewtonRootSolver.sqrt(1000000.0, 1e-6)));
            check("sqrt(0.0)", 0.0, round4(NewtonRootSolver.sqrt(0.0, 1e-9)));
            check("sqrt of a negative is NaN", true, Double.isNaN(NewtonRootSolver.sqrt(-4.0, 1e-9)));
            double seven = NewtonRootSolver.sqrt(7.0, 1e-6);
            check("sqrt(7.0) honours the tolerance", true, Math.abs(seven * seven - 7.0) <= 1e-6);
