public class NewtonRootSolver {

    public static double sqrt(double x, double tolerance) {
        if (x < 0) {
            return Double.NaN;
        }
        if (x == 0) {
            return 0.0;
        }
        double guess = 1.0;
        while (Math.abs(guess * guess - x) > tolerance) {
            guess = (guess + x / guess) / 2.0;
        }
        return guess;
    }
}
